CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid primary key default gen_random_uuid(),mobile varchar(15) unique not null,role varchar(30) not null default 'FARMER' check(role in ('FARMER','PROCUREMENT_OFFICER','CENTRE_OPERATOR','ADMIN')),status varchar(20) not null default 'ACTIVE',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS farmers(id uuid primary key default gen_random_uuid(),user_id uuid unique not null references users(id) on delete cascade,kisaan_code varchar(40) unique not null,name varchar(150) not null,village varchar(150),district varchar(100),state varchar(100),land_area_acres numeric(12,2),crops text[] not null default '{}',eligible_quantity_kg numeric(14,2) not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS centres(id uuid primary key default gen_random_uuid(),name varchar(180) not null,code varchar(50) unique not null,address text,district varchar(100),state varchar(100),latitude numeric(9,6),longitude numeric(9,6),daily_capacity integer not null check(daily_capacity>0),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS slots(id uuid primary key default gen_random_uuid(),centre_id uuid not null references centres(id),visit_date date not null,start_time time not null,end_time time not null,capacity integer not null check(capacity>0),status varchar(20) not null default 'ACTIVE' check(status in ('ACTIVE','CANCELLED','EXPIRED','COMPLETED')),valid_until date not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(centre_id,visit_date,start_time));
CREATE TABLE IF NOT EXISTS tokens(id uuid primary key default gen_random_uuid(),token_number varchar(60) unique not null,farmer_id uuid not null references farmers(id),slot_id uuid not null references slots(id),centre_id uuid not null references centres(id),desired_visit_date date not null,status varchar(30) not null check(status in ('PENDING','APPROVED','WAITING_FOR_APPROVAL','IN_QUEUE','PROCURED','CANCELLED','EXPIRED')),batch_number integer not null,batch_position integer not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_farmer_active_day ON tokens(farmer_id,desired_visit_date) WHERE status not in ('CANCELLED','EXPIRED');
CREATE TABLE IF NOT EXISTS procurement(id uuid primary key default gen_random_uuid(),token_id uuid unique not null references tokens(id),farmer_id uuid not null references farmers(id),centre_id uuid not null references centres(id),operator_id uuid references users(id),actual_quantity_kg numeric(14,2) not null check(actual_quantity_kg>=0),msp_per_kg numeric(12,2) not null check(msp_per_kg>=0),total_amount numeric(16,2) not null,receipt_number varchar(100),receipt_url text,status varchar(20) not null default 'CONFIRMED',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS payments(id uuid primary key default gen_random_uuid(),procurement_id uuid unique not null references procurement(id),amount numeric(16,2) not null,status varchar(20) not null default 'PENDING' check(status in ('PENDING','PAID')),paid_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS officer_profiles(id uuid primary key default gen_random_uuid(),user_id uuid unique references users(id) on delete cascade,employee_code varchar(60) unique,centre_id uuid references centres(id));
CREATE TABLE IF NOT EXISTS operator_profiles(id uuid primary key default gen_random_uuid(),user_id uuid unique references users(id) on delete cascade,employee_code varchar(60) unique,centre_id uuid references centres(id));
CREATE TABLE IF NOT EXISTS notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id) on delete cascade,title varchar(200) not null,message text not null,type varchar(30) not null default 'IN_APP',read_at timestamptz,created_at timestamptz not null default now());
CREATE INDEX IF NOT EXISTS idx_slots_date ON slots(visit_date,status);CREATE INDEX IF NOT EXISTS idx_tokens_slot_status ON tokens(slot_id,status);CREATE INDEX IF NOT EXISTS idx_tokens_centre_status ON tokens(centre_id,status);CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,created_at desc);
